{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C12", "C33", "C03"],
      "claim": "Nifedipine has consistently reported human oral bioavailability values of 35-68%, including an absolute F of 0.43 ± 0.14, supporting F >= 20%."
    },
    {
      "card_ids": ["C24", "C26", "C40", "C16", "C42"],
      "claim": "Several high-transferability evidence molecules show human oral bioavailability clearly above 20%, including 34%, 38%, 42%, 50%, and 90%."
    },
    {
      "card_ids": ["C35", "C04", "C34", "C28"],
      "claim": "Isradipine and pentazocine provide affirmative low-F evidence in healthy volunteers (about 16-19% and 11-18.5%, respectively), but these values are close to the threshold and condition-dependent."
    },
    {
      "card_ids": ["C17", "C21", "C01"],
      "claim": "Rigosertib absolute bioavailability is 34.8-35% in fasting patients, above the threshold, although the fed state lowers it to 13.9%."
    },
    {
      "card_ids": ["C33", "C24", "C26", "C40", "C16", "C42"],
      "claim": "The preponderance of direct human absolute or systemic bioavailability measurements across high-transferability evidence supports F >= 20%."
    }
  ],
  "confidence": "moderate",
  "contradictory_card_ids": ["C35", "C04", "C18", "C29", "C08", "C11", "C34", "C10", "C43", "C23", "C05", "C25", "C31", "C28", "C15", "C01"],
  "decision_summary": "Predicted high (F >= 20%) because most high-transferability evidence molecules have human oral bioavailability values above 20%, including multiple absolute measurements; conflicting low values from isradipine and pentazocine are condition-dependent and outweighed.",
  "evidence_gaps": [
    "Some records are qualitative ('good', 'high') without numeric F values.",
    "Fed-state and cirrhosis conditions alter bioavailability in several evidence molecules, creating condition-dependent variability.",
    "Conflicting healthy-volunteer F values near the 20% threshold for isradipine and pentazocine add uncertainty."
  ],
  "new_evidence_assessment": [],
  "prediction_basis_card_ids": ["C33", "C24", "C26", "C40", "C16", "C42", "C17", "C21", "C12"],
  "revision_action": "initial",
  "supportive_card_ids": ["C12", "C06", "C39", "C27", "C38", "C37", "C09", "C03", "C30", "C33", "C24", "C02", "C26", "C13", "C22", "C40", "C41", "C32", "C20", "C07", "C14", "C36", "C19", "C17", "C21", "C16", "C42"]
}

